//! The unconditional certificate for the class group, the class number and
//! the regulator (Sage's proof=True): no GRH, at the price of work about
//! sqrt|d_K|, so for small discriminants only.
//!
//! bnfinit (nf/bnf.rs) finds relations (e_i) = prod_P P^(v_i) over the
//! factor base S (the prime ideals of norm below its bound).  Let L be the
//! lattice the v_i span in Z^S, h* = [Z^S : L], and Gamma the group
//! generated by the e_i and the roots of unity.  The certificate proves:
//!
//! 1. S generates the class group.  Every ideal class contains an integral
//!    ideal of norm at most M = min(Minkowski, Zimmert) sqrt|d| (nf/
//!    zimmert.rs), so the prime ideals of norm <= M generate.  Each prime
//!    ideal P of norm in [bound, M], in increasing norm, is shown to lie in
//!    the subgroup S generates by an element x of P with (x) = P Q_1^a_1
//!    ... where every Q_j is in S or already shown (valuations and the norm
//!    of x computed exactly).  Then Z^S / Lambda = Cl for the lattice
//!    Lambda of all relations, and h* is a multiple of h.
//!
//! 2. The units.  Integer kernel vectors of the relation matrix give units
//!    of Gamma (compact representations: products of the e_i); their
//!    logarithms, with certified error bounds, give units u_1..u_r spanning
//!    a full sublattice U' (with the roots of unity) of the unit group, and
//!    an enclosure of its regulator R' (nf/certify.rs regulator_bounds).
//!    With Zimmert's lower bound R >= R_low (Satz 3),
//!    [O* : U'] = R'/R <= R'/R_low =: B.  For each prime l <= B, U' is
//!    shown l-saturated: power-residue characters chi_Q (Q a degree-1 prime
//!    outside S, N Q = 1 mod l) on zeta (if l | w), u_1..u_r have full rank
//!    r + [l | w], so no element of U' outside U'^l is an l-th power in K,
//!    and l does not divide [O* : U'].  Hence U' = O* and R = R'.
//!
//! 3. h* = h.  [Lambda : L] divides h*.  For each prime l | h*, Gamma is
//!    shown l-saturated in the S-units U_S: with Gamma_l the elements of
//!    Gamma whose valuations are divisible by l, dim(Gamma_l / Gamma^l) <=
//!    r + [l | w] + t_l (t_l = dim (Z^S/L)[l] = |S| - rank_l(M)), and the
//!    characters have rank at least that on Gamma_l / Gamma^l, computed as
//!    rank_l [M | X] - rank_l M with X the characters of the e_i (and of
//!    zeta).  So an S-unit x with x^l in Gamma is in Gamma; l does not
//!    divide [U_S : Gamma] = [Lambda : L] [O* : Gamma n O*].  Hence L =
//!    Lambda, h = h*, and Cl = Z^S / L.
//!
//! Step 3's saturation argument is the one in Elsenhans and Voight,
//! "Computing class groups and unit groups in Magma" (arXiv:2510.05501),
//! Sections 6-7 (reduction modulo primes); the bounds are Minkowski's and
//! Zimmert's (Invent. Math. 62 (1981), Satz 2 and 3); Buchmann's algorithm
//! for the relations is Cohen, GTM 138, 6.5.  Every step is exact except
//! the regulator's and the bounds' real numbers, which are balls.
//!
//! Beyond `Limits` (M, or the number of primes l to check) the certificate
//! refuses: the error says which bound was exceeded and by how much.

use super::bnf::{bnfinit_with, kernel_lattice, unit_lattice, Relations};
use super::embed::{lll, Embeddings};
use super::order::{maximal_order_assuming, Order};
use super::prime::{decompose, valuation, PrimeIdeal};
use super::zimmert::{class_norm_bound, regulator_lower, NormBound};
use super::zlin::{vec_mat, ZMat};
use crate::arith::{mulmod, powmod, primes_up_to};
use crate::relations::is_prime_u64;
use num_integer::Integer;
use num_traits::{One, Signed, ToPrimitive, Zero};
use sagebrush_ball::{Ball, Mag};
use sagebrush_bigint::BigInt;
use std::collections::{HashMap, HashSet};

/// The largest certificate attempted: M (the norm bound of step 1) and B
/// (the bound on the unit index of step 2).
#[derive(Clone, Copy, Debug)]
pub struct Limits {
    pub norm_max: u64,
    pub index_max: u64,
}

impl Default for Limits {
    fn default() -> Limits {
        Limits { norm_max: 1_000_000, index_max: 1_000_000 }
    }
}

/// The prefix of the errors that are refusals (beyond `Limits`), not
/// failures.
pub const REFUSED: &str = "beyond the limits of the unconditional certificate";

/// A proven class group and regulator, with what the proof used.
#[derive(Clone, Debug)]
pub struct Proof {
    pub n: usize,
    pub r1: usize,
    pub r2: usize,
    pub disc: BigInt,
    pub h: BigInt,
    pub cyc: Vec<BigInt>,
    pub w: u32,
    /// the regulator: reg_fixed / 2^prec, correct to reg_digits significant
    /// digits (1 and prec 0 for unit rank 0); reg_lo, reg_hi an enclosure
    pub reg_fixed: BigInt,
    pub prec: u32,
    pub reg_digits: usize,
    pub reg_lo: f64,
    pub reg_hi: f64,
    /// step 1: the norm bound M, which bound gave it, the factor base's
    /// bound, and the number of prime ideals shown to lie in its subgroup
    pub norm_bound: BigInt,
    pub norm_bound_kind: NormBound,
    pub fb_bound: u64,
    pub primes_shown: usize,
    /// step 2: Zimmert's lower bound for R (lower end), the index bound B
    /// and the number of primes l <= B checked
    pub reg_lower: f64,
    pub index_bound: u64,
    pub unit_primes: usize,
    /// step 3: the primes l dividing h* checked
    pub class_primes: Vec<BigInt>,
    /// the fundamental units, as exponent vectors over the relation
    /// elements
    pub units: Vec<Vec<BigInt>>,
    /// seconds per stage (bnfinit, units, generation, unit saturation,
    /// class saturation)
    pub timing: Vec<(&'static str, f64)>,
}

fn refuse(what: &str, value: &BigInt, limit: u64) -> String {
    let ratio = value.to_f64().unwrap_or(f64::INFINITY) / limit as f64;
    format!("{}: {} is {}, above the limit {} ({:.3} times it)", REFUSED, what, value, limit, ratio)
}

/// The certificate for the field Q[x]/(f) (f monic, integral).
pub fn certify(f: &[BigInt], limits: &Limits) -> Result<Proof, String> {
    // the discriminant and signature first: the norm bound decides whether
    // to start at all
    let (o0, _, assumed) = maximal_order_assuming(f)?;
    if !assumed.is_empty() {
        let ps: Vec<String> = assumed.iter().map(|p| p.to_string()).collect();
        return Err(format!("the maximal order assumes {} prime (probable primes, not proven)", ps.join(", ")));
    }
    let emb0 = Embeddings::new(&o0)?;
    let (r1, r2) = (emb0.r1, emb0.r2);
    let n = o0.n;
    let dk = o0.disc();
    let (mbound, kind) = class_norm_bound(r1, r2, &dk).ok_or("the norm bound could not be evaluated")?;
    if mbound > BigInt::from(limits.norm_max) {
        return Err(refuse(&format!("the {} bound for the norms of ideal class representatives", kind.name()), &mbound, limits.norm_max));
    }
    let mbound = mbound.to_u64().unwrap();
    let mut timing = vec![];
    let mut clock = crate::clock::Instant::now();
    let debug = std::env::var("PROOF_DEBUG").is_ok();
    let mut lap = |name: &'static str, timing: &mut Vec<(&'static str, f64)>| {
        if debug {
            eprintln!("  proof: {} {:.1} ms", name, clock.elapsed().as_secs_f64() * 1e3);
        }
        timing.push((name, clock.elapsed().as_secs_f64()));
        clock = crate::clock::Instant::now();
    };
    let (b, _, rel) = bnfinit_with(f, &[])?;
    lap("bnfinit", &mut timing);
    if !b.w_proven {
        return Err("the number of roots of unity is not proven".into());
    }
    let w = b.w;
    let o = &rel.order;
    let emb = Embeddings::new(o)?;
    let r = r1 + r2 - 1;
    let c = rel.fb.len();
    check_relations(o, &rel)?;
    check_factor_base(o, &rel)?;
    // the relation matrix (k x c) and its lattice L
    let dense: Vec<Vec<i64>> = rel.rels.iter().map(|rl| {
        let mut row = vec![0i64; c];
        for &(i, e) in rl {
            row[i] = e;
        }
        row
    }).collect();
    let sel = crate::linalg::independent_rows(&dense, c).map_err(|_| "the relations do not have full rank".to_string())?;
    // Z^c / L from the structured elimination's core (columns with a +-1
    // entry expressed through the others: Z^c / L unchanged), which is
    // small; the full matrix can have thousands of rows
    let (hstar, cyc) = match crate::linalg::eliminate(c, &rel.rels, 80) {
        crate::linalg::Reduced::Deficient(_) => return Err("the relations do not have full rank".into()),
        crate::linalg::Reduced::Core(cols, core) => {
            let cc = cols.len();
            let csel = if cc == 0 { vec![] } else { crate::linalg::independent_rows(&core, cc).map_err(|_| "the relations do not have full rank".to_string())? };
            class_group_of(&core, &csel, cc)?
        }
    };
    // step 2 first (cheap, and B decides whether to go on)
    let zeta = root_of_unity_generator(o, &emb, w).ok_or("no generator of the roots of unity found")?;
    let units = if r == 0 { None } else { Some(units_near(o, &emb, &rel.elems, &dense, &sel, r, b.regulator)?) };
    lap("units", &mut timing);
    let r_low = regulator_lower(r1, r2, w, 128).ok_or("Zimmert's regulator bound could not be evaluated")?;
    let (index_bound, unit_exps) = match &units {
        None => (1u64, vec![]),
        Some(u) => {
            // B = floor(R'_hi / R_low), from the balls' ends
            let (lm, le) = r_low.lower();
            let low = Ball::exact(lm, le);
            if !low.is_positive() {
                return Err("Zimmert's regulator bound is not positive".into());
            }
            let q = u.hi.div(&low, 128).ok_or("R'/R_low")?;
            let (qm, qe) = q.upper();
            let bnd = if qe >= 0 { qm << qe as u64 } else { qm >> (-qe) as u64 };
            if bnd > BigInt::from(limits.index_max) {
                return Err(refuse("the bound on the index of the units found in the unit group (regulator found / Zimmert's lower bound)", &bnd, limits.index_max));
            }
            (bnd.to_u64().unwrap(), u.exps.clone())
        }
    };
    // step 1
    let primes_shown = prove_generation(o, &emb, &dk, rel.bound, mbound, &rel.fb)?;
    lap("generation", &mut timing);
    // characters
    let chars = Chars::new(o, &rel.elems, &zeta, rel.bound);
    // step 2: l <= B
    let mut unit_primes = 0;
    if r > 0 {
        for l in primes_up_to(index_bound) {
            sagebrush_interrupt::check();
            unit_saturated(&chars, &unit_exps, w, l)?;
            unit_primes += 1;
        }
    }
    lap("unit saturation", &mut timing);
    // step 3: l | h*
    let mut class_primes = vec![];
    if !hstar.is_one() {
        for (l, _) in crate::api::factor_integer(&hstar)? {
            sagebrush_interrupt::check();
            let lu = l.to_u64().ok_or("a prime factor of h* beyond 64 bits")?;
            class_saturated(&chars, &dense, c, r, w, lu)?;
            class_primes.push(l);
        }
    }
    lap("class saturation", &mut timing);
    let (reg_fixed, prec, reg_digits, reg_lo, reg_hi) = match &units {
        None => (BigInt::one(), 0, 20, 1.0, 1.0),
        Some(u) => (u.reg_fixed.clone(), u.prec, u.digits, super::bnf::lower_f64(&u.lo), upper_f64(&u.hi)),
    };
    Ok(Proof {
        n, r1, r2, disc: dk, h: hstar, cyc, w, reg_fixed, prec, reg_digits, reg_lo, reg_hi,
        norm_bound: BigInt::from(mbound), norm_bound_kind: kind, fb_bound: rel.bound, primes_shown,
        reg_lower: super::bnf::lower_f64(&r_low), index_bound, unit_primes, class_primes, units: unit_exps, timing,
    })
}

fn upper_f64(b: &Ball) -> f64 {
    let (m, e) = b.upper();
    Ball::exact(m, e).to_f64_approx()
}

/// The factor base is every prime ideal of norm below its bound (step 1
/// relies on it): as many as decompose finds, each of norm below it.
fn check_factor_base(o: &Order, rel: &Relations) -> Result<(), String> {
    let dk = o.disc();
    let mut count = 0;
    for p in primes_up_to(rel.bound.saturating_sub(1)) {
        for q in decompose_checked(o, &dk, p)? {
            if q.norm() < BigInt::from(rel.bound) {
                count += 1;
            }
        }
    }
    if count != rel.fb.len() || rel.fb.iter().any(|q| q.norm() >= BigInt::from(rel.bound)) {
        return Err(format!("the factor base is not every prime ideal of norm below {}", rel.bound));
    }
    Ok(())
}

/// Every relation checked exactly: (e_i) = prod P^v, by v_P(e_i) = v for
/// each P listed and |N(e_i)| = prod N(P)^v (so no other prime divides).
fn check_relations(o: &Order, rel: &Relations) -> Result<(), String> {
    for (rl, x) in rel.rels.iter().zip(&rel.elems) {
        sagebrush_interrupt::check();
        let mut prod = BigInt::one();
        for &(i, v) in rl {
            let q = &rel.fb[i];
            if v <= 0 || valuation(o, q, x) as i64 != v {
                return Err(format!("a relation's valuation at a prime above {} is wrong", q.p));
            }
            prod *= q.norm().pow(v as u32);
        }
        if o.norm(x).abs() != prod {
            return Err("a relation's element has a prime factor outside its relation".into());
        }
    }
    Ok(())
}

/// [Z^c : L] and the invariants of Z^c / L (the elementary divisors > 1,
/// each dividing the next), L spanned by the rows of `dense`, of rank c
/// (`sel`: c independent rows).  L contains D Z^c for D = det of the sel
/// rows (D e_j are combinations of them by the adjugate), so its HNF is
/// computed modulo D; then the generators whose HNF pivot is 1 are
/// eliminated before the Smith form.
fn class_group_of(dense: &[Vec<i64>], sel: &[usize], c: usize) -> Result<(BigInt, Vec<BigInt>), String> {
    if c == 0 {
        return Ok((BigInt::one(), vec![]));
    }
    let a: Vec<Vec<i64>> = sel.iter().map(|&k| dense[k].clone()).collect();
    let d = crate::linalg::det_crt(&a).abs();
    if d.is_zero() {
        return Err("the relations do not have full rank".into());
    }
    let rows: ZMat = dense.iter().map(|row| row.iter().map(|&x| BigInt::from(x)).collect()).collect();
    let h = super::bnf::hnf_mod_d(&rows, &d);
    if h.len() != c || (0..c).any(|i| h[i][i].is_zero()) {
        return Err("the relation lattice's HNF is not square".into());
    }
    let hstar: BigInt = (0..c).map(|i| h[i][i].clone()).product();
    // e_i with pivot 1: e_i = -sum_(j>i) h_ij e_j; substitute from the
    // bottom up, then the rows of the other pivots are the relations among
    // the remaining generators (all reduced modulo h*, which kills Z^c/L)
    let keep: Vec<usize> = (0..c).filter(|&i| !h[i][i].is_one()).collect();
    let pos: HashMap<usize, usize> = keep.iter().enumerate().map(|(k, &i)| (i, k)).collect();
    let m = keep.len();
    // expr[i]: e_i in terms of the kept generators
    let mut expr: Vec<Vec<BigInt>> = vec![vec![]; c];
    for i in (0..c).rev() {
        let mut v = vec![BigInt::zero(); m];
        if let Some(&k) = pos.get(&i) {
            v[k] = BigInt::one();
        } else {
            for j in i + 1..c {
                if !h[i][j].is_zero() {
                    for (t, x) in expr[j].iter().enumerate() {
                        v[t] = (&v[t] - &h[i][j] * x).mod_floor(&hstar);
                    }
                }
            }
        }
        expr[i] = v;
    }
    let mut rel: ZMat = keep.iter().map(|&i| {
        let mut v = vec![BigInt::zero(); m];
        for j in i..c {
            if !h[i][j].is_zero() {
                for (t, x) in expr[j].iter().enumerate() {
                    v[t] = (&v[t] + &h[i][j] * x).mod_floor(&hstar);
                }
            }
        }
        v
    }).collect();
    for t in 0..m {
        rel.push((0..m).map(|j| if j == t { hstar.clone() } else { BigInt::zero() }).collect());
    }
    let mut cyc: Vec<BigInt> = if m == 0 { vec![] } else { crate::api::elementary_divisors(&rel) };
    cyc.retain(|x| !x.is_one() && !x.is_zero());
    cyc.reverse(); // Sage's order: each a multiple of the next
    let prod: BigInt = cyc.iter().product();
    if prod != hstar {
        return Err(format!("the class group's invariants {:?} do not multiply to h* = {}", cyc, hstar));
    }
    Ok((hstar, cyc))
}

/// A generator of the roots of unity (order w), order coordinates: -1 for
/// w = 2, else one of the elements with T2 = n (Kronecker) of order
/// exactly w, checked exactly.
fn root_of_unity_generator(o: &Order, emb: &Embeddings, w: u32) -> Option<Vec<BigInt>> {
    let one = o.one();
    if w == 2 {
        return Some(one.iter().map(|x| -x).collect());
    }
    let n = o.n;
    let id: ZMat = (0..n).map(|i| (0..n).map(|j| BigInt::from((i == j) as i32)).collect()).collect();
    let red = lll(&id, emb);
    let g = emb.t2_gram(&red);
    let pw = |x: &[BigInt], e: u32| -> Vec<BigInt> {
        let mut acc = one.clone();
        for _ in 0..e {
            acc = o.mul(&acc, x);
        }
        acc
    };
    let qs: Vec<u32> = (2..=w).filter(|q| w % q == 0 && (2..*q).all(|d| q % d != 0)).collect();
    for cand in super::bnf::short_vectors(&g, n as f64 * (1.0 + 1e-9), 1000) {
        let x: Vec<BigInt> = (0..n).map(|k| cand.iter().zip(&red).map(|(ci, row)| BigInt::from(*ci) * &row[k]).sum()).collect();
        if pw(&x, w) == one && qs.iter().all(|&q| pw(&x, w / q) != one) {
            return Some(x);
        }
    }
    None
}

// ---------------------------------------------------------------- step 1

/// Shows that every prime ideal of norm in [bound, mbound] lies in the
/// subgroup of the class group generated by those of norm < bound (step
/// 1); returns how many were shown.  The elements tried: small
/// combinations of an LLL-reduced basis of P, then of P Q for random
/// factor-base primes Q (fb: those of norm < bound; in P Q, Q only adds a
/// factor already in the subgroup), so that there are always fresh
/// candidates (in degree 2, P alone has few small elements).
fn prove_generation(o: &Order, emb: &Embeddings, dk: &BigInt, bound: u64, mbound: u64, fb: &[PrimeIdeal]) -> Result<usize, String> {
    if mbound < bound {
        return Ok(0);
    }
    let n = o.n;
    let mut cache: HashMap<u64, Vec<PrimeIdeal>> = HashMap::new();
    // the prime ideals to show, by increasing norm
    let mut todo: Vec<(u64, u64, usize)> = vec![];
    for p in primes_up_to(mbound) {
        sagebrush_interrupt::check();
        let ps = decompose_checked(o, dk, p)?;
        for (i, q) in ps.iter().enumerate() {
            if let Some(nq) = p.checked_pow(q.f) {
                if nq >= bound && nq <= mbound {
                    todo.push((nq, p, i));
                }
            }
        }
        if p < 1 << 12 {
            cache.insert(p, ps);
        }
    }
    todo.sort();
    // prime ideals shown (of norm >= bound), as (p, index in decompose(p))
    let mut shown: HashSet<(u64, usize)> = HashSet::new();
    let mut rng = 0x5DEE_CE66_D1CE_4E5Bu64;
    for &(np, p, i) in &todo {
        sagebrush_interrupt::check();
        let pr = decompose_cached(&mut cache, o, dk, p)?[i].clone();
        let mut red = lll(&pr.basis, emb);
        let mut done = false;
        for attempt in 0..2000 {
            let mut next = || {
                rng ^= rng << 13;
                rng ^= rng >> 7;
                rng ^= rng << 17;
                rng
            };
            // every 40 attempts after the first 100, a new ideal P Q
            let fresh = attempt >= 100 && attempt % 40 == 0 && !fb.is_empty();
            if fresh {
                let q = &fb[(next() % fb.len().min(30) as u64) as usize];
                red = lll(&super::bnf::ideal_mul(o, &pr.basis, &q.basis), emb);
            }
            let start = if attempt < 100 { 0 } else { attempt - attempt % 40 };
            // the reduced basis, then random small combinations
            let coef: Vec<i64> = if attempt - start < n {
                (0..n).map(|j| (j == attempt - start) as i64).collect()
            } else {
                (0..n).map(|_| (next() % 7) as i64 - 3).collect()
            };
            if coef.iter().all(|&x| x == 0) {
                continue;
            }
            let x: Vec<BigInt> = (0..n).map(|k| coef.iter().zip(&red).map(|(&ci, row)| &row[k] * ci).sum()).collect();
            if shows(o, dk, &mut cache, &x, np, p, i, bound, &shown)? {
                done = true;
                break;
            }
        }
        if !done {
            return Err(format!("could not show that a prime ideal above {} (norm {}) lies in the subgroup generated by the factor base", p, np));
        }
        shown.insert((p, i));
    }
    Ok(todo.len())
}

/// decompose, checking sum e f = n (every prime ideal above p found).
fn decompose_checked(o: &Order, dk: &BigInt, p: u64) -> Result<Vec<PrimeIdeal>, String> {
    let ps = decompose(o, dk, p)?;
    if ps.iter().map(|q| (q.e * q.f) as usize).sum::<usize>() != o.n {
        return Err(format!("the prime ideals above {} are incomplete", p));
    }
    Ok(ps)
}

fn decompose_cached<'a>(cache: &'a mut HashMap<u64, Vec<PrimeIdeal>>, o: &Order, dk: &BigInt, p: u64) -> Result<&'a Vec<PrimeIdeal>, String> {
    if !cache.contains_key(&p) {
        if cache.len() > 50_000 {
            cache.retain(|&q, _| q < 1 << 12);
        }
        cache.insert(p, decompose_checked(o, dk, p)?);
    }
    Ok(&cache[&p])
}

/// Whether x (in P, the i-th prime above p, of norm np) shows that P lies
/// in the subgroup: v_P(x) = 1 and every other prime ideal dividing x has
/// norm < bound or is in `shown`, the factorization being complete
/// (sum over Q | q of v_Q f_Q = v_q(N x) for every prime q).
#[allow(clippy::too_many_arguments)]
fn shows(o: &Order, dk: &BigInt, cache: &mut HashMap<u64, Vec<PrimeIdeal>>, x: &[BigInt], np: u64, p: u64, i: usize, bound: u64, shown: &HashSet<(u64, usize)>) -> Result<bool, String> {
    let nx = o.norm(x).abs();
    if nx.is_zero() {
        return Ok(false);
    }
    let (m, rem) = nx.div_rem(&BigInt::from(np));
    if !rem.is_zero() {
        return Err("an element of a prime ideal whose norm is not divisible by the ideal's".into());
    }
    // the rational primes of N(x): all at most np (a prime ideal above a
    // larger one has a larger norm, not yet shown)
    let mut qs: Vec<u64> = vec![p];
    let mut rest = m;
    for (q, _) in small_factors(&rest, np)? {
        qs.push(q);
        while (&rest % q).is_zero() {
            rest /= q;
        }
    }
    if !rest.is_one() {
        return Ok(false);
    }
    qs.sort();
    qs.dedup();
    for &q in &qs {
        let mut vq = 0u32;
        let mut t = nx.clone();
        while (&t % q).is_zero() {
            t /= q;
            vq += 1;
        }
        let ps = decompose_cached(cache, o, dk, q)?.clone();
        let mut seen = 0u32;
        for (j, qq) in ps.iter().enumerate() {
            let v = valuation(o, qq, x);
            seen += v * qq.f;
            if v == 0 {
                continue;
            }
            if q == p && j == i {
                if v != 1 {
                    return Ok(false);
                }
                continue;
            }
            let nq = q.checked_pow(qq.f);
            let ok = nq.is_some_and(|nq| nq < bound) || shown.contains(&(q, j));
            if !ok {
                return Ok(false);
            }
        }
        if seen != vq {
            return Err(format!("the valuations at the primes above {} do not account for the norm", q));
        }
    }
    Ok(true)
}

/// The prime factors of m if all are at most `max` (else whatever was
/// found: the caller checks that they account for m): trial division up to
/// 2^16, then the general factorization.
fn small_factors(m: &BigInt, max: u64) -> Result<Vec<(u64, u32)>, String> {
    let mut out = vec![];
    let mut t = m.clone();
    let mut d = 2u64;
    while d < 1 << 16 && d <= max {
        if t.is_one() {
            return Ok(out);
        }
        if (&t % d).is_zero() {
            let mut e = 0;
            while (&t % d).is_zero() {
                t /= d;
                e += 1;
            }
            out.push((d, e));
        }
        d += 1 + (d > 2) as u64;
    }
    if t.is_one() {
        return Ok(out);
    }
    if t > BigInt::from(max).pow(4) {
        return Ok(out); // a factor beyond max is certain
    }
    for (q, e) in crate::api::factor_integer(&t)? {
        match q.to_u64() {
            Some(q) if q <= max => out.push((q, e)),
            _ => return Ok(out),
        }
    }
    Ok(out)
}

// ---------------------------------------------------------------- step 2

struct Units {
    lo: Ball,
    hi: Ball,
    reg_fixed: BigInt,
    prec: u32,
    digits: usize,
    /// r rows: exponents over the relation elements
    exps: Vec<Vec<BigInt>>,
}

/// certified_units from the sel rows and r + 6, 2 (r + 6), ... of the other
/// relations (spread over them) until the regulator found is that of the
/// GRH computation, `target` (only a target: if it were wrong, step 2
/// would fail, never accept), or every relation is used.
fn units_near(o: &Order, emb: &Embeddings, elems: &[Vec<BigInt>], dense: &[Vec<i64>], sel: &[usize], r: usize, target: f64) -> Result<Units, String> {
    let k = dense.len();
    let in_sel: HashSet<usize> = sel.iter().cloned().collect();
    let others: Vec<usize> = (0..k).filter(|i| !in_sel.contains(i)).collect();
    let mut n_extra = r + 6;
    loop {
        let extras: Vec<usize> = if n_extra >= others.len() { others.clone() } else {
            let mut v: Vec<usize> = (0..n_extra).map(|t| others[t * 7919 % others.len()]).collect();
            v.sort();
            v.dedup();
            v
        };
        let t = crate::clock::Instant::now();
        let res = certified_units(o, emb, elems, dense, sel, &extras, r);
        if std::env::var("PROOF_DEBUG").is_ok() {
            eprintln!("  proof: units from {} rows + {} extras: {:?} in {:.1} ms", sel.len(), extras.len(), res.as_ref().map(|u| super::bnf::lower_f64(&u.lo)), t.elapsed().as_secs_f64() * 1e3);
        }
        let done = match &res {
            Ok(u) => super::bnf::lower_f64(&u.lo) <= target * (1.0 + 1e-6),
            Err(_) => false,
        };
        if done || extras.len() >= others.len() {
            return res;
        }
        n_extra *= 2;
    }
}

/// Units u_1..u_r of Gamma spanning (with the roots of unity) a sublattice
/// of the unit group, with an enclosure of its regulator: integer kernel
/// vectors of the relation matrix's rows sel and extras (each an exact
/// unit, checked: E M = 0), their logarithms with certified error bounds,
/// and regulator_bounds' integral T (u = T E).
fn certified_units(o: &Order, emb: &Embeddings, elems: &[Vec<BigInt>], dense: &[Vec<i64>], sel: &[usize], extras: &[usize], r: usize) -> Result<Units, String> {
    let k = dense.len();
    let a: Vec<Vec<i64>> = sel.iter().map(|&i| dense[i].clone()).collect();
    let vs: Vec<Vec<i64>> = extras.iter().map(|&i| dense[i].clone()).collect();
    if vs.is_empty() {
        return Err("no relations beyond a basis: no units".into());
    }
    let tk = crate::clock::Instant::now();
    let (d, ys) = crate::linalg::kernel_crt(&a, &vs);
    if std::env::var("PROOF_DEBUG").is_ok() {
        eprintln!("    kernel_crt {} x {} + {}: d {} bits in {:.1} ms", a.len(), a.first().map_or(0, |x| x.len()), vs.len(), d.bits(), tk.elapsed().as_secs_f64() * 1e3);
    }
    if d.is_zero() {
        return Err("the relations do not have full rank".into());
    }
    // the kernel of M: z with z Y = 0 mod d gives (z Y / d on the sel rows,
    // -z on the extras)
    let mut exps: Vec<Vec<BigInt>> = vec![];
    for z in kernel_lattice(&ys, &d) {
        let mut e = vec![BigInt::zero(); k];
        for (col, &s) in sel.iter().enumerate() {
            let t: BigInt = z.iter().zip(&ys).map(|(zt, y)| zt * &y[col]).sum();
            let (q, rem) = t.div_rem(&d);
            if !rem.is_zero() {
                return Err("a kernel vector is not integral".into());
            }
            e[s] = q;
        }
        for (zt, &x) in z.iter().zip(extras) {
            e[x] = -zt;
        }
        // E M = 0 exactly
        let c = dense[0].len();
        if (0..c).any(|j| e.iter().zip(dense).map(|(ei, row)| ei * row[j]).sum::<BigInt>() != BigInt::zero()) {
            return Err("a kernel vector is not in the kernel".into());
        }
        if e.iter().any(|x| !x.is_zero()) {
            exps.push(e);
        }
    }
    let ebits = exps.iter().flatten().map(|x| x.bits()).max().unwrap_or(1) as u32;
    let mut prec = ebits + 128 + 4 * (k as u32).max(1).ilog2();
    let mut rank_short = false;
    for _ in 0..6 {
        sagebrush_interrupt::check();
        let (roots, rho) = emb.roots_hp_rad(&o.f, prec)?;
        let mut logs = Vec::with_capacity(k);
        let mut errs = Vec::with_capacity(k);
        let mut ok = true;
        for x in elems {
            match emb.log_embedding_err(o, x, &roots, &rho, prec) {
                Some((l, e)) => {
                    logs.push(l);
                    errs.push(e);
                }
                None => {
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            let lams: Vec<Vec<BigInt>> = exps.iter().map(|e| (0..r).map(|j| e.iter().zip(&logs).filter(|(c, _)| !c.is_zero()).map(|(c, l)| c * &l[j]).sum()).collect()).collect();
            let lerr: Vec<Mag> = exps.iter().map(|e| e.iter().zip(&errs).filter(|(c, _)| !c.is_zero()).fold(Mag::ZERO, |acc, (c, &er)| acc.add(Mag::from_bigint_up(c, 0).mul(er)))).collect();
            let worst = lerr.iter().fold(Mag::ZERO, |a, &b| a.max(b));
            if let Some((wm, we)) = worst.to_dyadic() {
                let err = if we >= 0 { (wm << we as u64) + 1u32 } else { (wm >> (-we) as u64) + 1u32 };
                match unit_lattice(&lams, r, &err, prec) {
                    Ok((basis, _)) => match super::certify::regulator_bounds_t(&lams, &lerr, &basis, prec) {
                        Ok((lo, hi, dd, rel, t)) => {
                            let units: Vec<Vec<BigInt>> = t.iter().map(|ti| (0..k).map(|col| ti.iter().zip(&exps).filter(|(c, _)| !c.is_zero()).map(|(c, e)| c * &e[col]).sum()).collect()).collect();
                            let digits = ((-rel.log10()).floor() as i64 - 1).clamp(1, 20) as usize;
                            let reg_fixed = &dd >> (prec as usize * (r - 1));
                            return Ok(Units { lo, hi, reg_fixed, prec, digits, exps: units });
                        }
                        Err(false) => return Err("the units found are of rank below r".into()),
                        Err(true) => {} // more precision
                    },
                    // rank below r with every vector used, twice (once may
                    // be the precision): more relations, not more precision
                    Err(true) if rank_short => return Err("the units found are of rank below r".into()),
                    Err(true) => rank_short = true,
                    Err(false) => {}
                }
            }
        }
        prec *= 2;
    }
    Err("the unit lattice could not be certified (precision)".into())
}

// ------------------------------------------------------------ characters

/// Power-residue characters at degree-1 primes Q = (p, theta - a) outside
/// the factor base (p >= its bound, p prime to disc(f) and the order's
/// denominator, so the reduction O -> F_p is x -> x(a)).
struct Chars {
    f: Vec<BigInt>,
    disc_f: BigInt,
    den: BigInt,
    start: u64,
    /// the relation elements and zeta on the power basis (numerators over den)
    elems: Vec<Vec<BigInt>>,
    zeta: Vec<BigInt>,
}

impl Chars {
    fn new(o: &Order, elems: &[Vec<BigInt>], zeta: &[BigInt], bound: u64) -> Chars {
        Chars {
            f: o.f.clone(),
            disc_f: Order::equation_order(&o.f).disc(),
            den: o.den.clone(),
            start: bound.max(3),
            elems: elems.iter().map(|x| vec_mat(x, &o.basis)).collect(),
            zeta: vec_mat(zeta, &o.basis),
        }
    }

    /// The primes Q for l: (p, a) with p = 1 mod l, from the smallest p
    /// >= start on.
    fn primes(&self, l: u64) -> impl Iterator<Item = (u64, u64)> + '_ {
        let j0 = self.start.div_ceil(l).max(1);
        (j0..).map(move |j| j * l + 1).filter(move |&p| {
            is_prime_u64(p) && !(&self.disc_f % p).is_zero() && !(&self.den % p).is_zero()
        }).flat_map(move |p| {
            sagebrush_poly::factor_mod(&self.f, p).into_iter().filter(|(g, _)| g.len() == 2).map(move |(g, _)| {
                // g = x + g0 (monic)
                (p, (p - g[0] % p) % p)
            }).collect::<Vec<_>>()
        })
    }
}

/// x(a) mod p for x = sum num_j theta^j / den.
fn reduce(num: &[BigInt], den_inv: u64, a: u64, p: u64) -> u64 {
    let bp = BigInt::from(p);
    let mut acc = 0u64;
    for c in num.iter().rev() {
        let cm = c.mod_floor(&bp).to_u64().unwrap();
        acc = (mulmod(acc, a, p) + cm) % p;
    }
    mulmod(acc, den_inv, p)
}

/// Discrete logarithms in the subgroup of order l of F_p^*: baby steps
/// eta^j (j < s) in a table, giant steps by eta^-s.
struct Dlog {
    p: u64,
    l: u64,
    s: u64,
    table: HashMap<u64, u64>,
    giant: u64,
}

impl Dlog {
    fn new(p: u64, l: u64) -> Dlog {
        let e = (p - 1) / l;
        let eta = (2..p).map(|t| powmod(t, e, p)).find(|&y| y != 1).expect("p = 1 mod l");
        let s = (l as f64).sqrt().ceil() as u64 + 1;
        let mut table = HashMap::with_capacity(s as usize);
        let mut x = 1u64;
        for j in 0..s {
            table.entry(x).or_insert(j);
            x = mulmod(x, eta, p);
        }
        // eta^-s = eta^(l - s mod l)
        let giant = powmod(eta, (l - s % l) % l, p);
        Dlog { p, l, s, table, giant }
    }

    /// k with eta^k = y (y of order dividing l).
    fn log(&self, y: u64) -> Result<u64, String> {
        let mut g = y;
        for i in 0..=self.s {
            if let Some(&j) = self.table.get(&g) {
                return Ok((i * self.s + j) % self.l);
            }
            g = mulmod(g, self.giant, self.p);
        }
        Err("a power-residue symbol outside the subgroup of order l".into())
    }

    /// chi(x) = log(x^((p-1)/l)) for x in F_p^*.
    fn chi(&self, x: u64) -> Result<u64, String> {
        if x == 0 {
            return Err("an element of Gamma vanishes at a character prime".into());
        }
        self.log(powmod(x, (self.p - 1) / self.l, self.p))
    }
}

/// Vectors over F_l in echelon form (by pivot position), for the rank of a
/// growing set.
struct Echelon {
    l: u64,
    rows: Vec<(usize, Vec<u64>)>,
}

impl Echelon {
    fn new(l: u64) -> Echelon {
        Echelon { l, rows: vec![] }
    }

    /// Adds v; whether the rank grew.
    fn add(&mut self, mut v: Vec<u64>) -> bool {
        let l = self.l;
        for (piv, row) in &self.rows {
            let f = v[*piv];
            if f != 0 {
                for (x, y) in v.iter_mut().zip(row) {
                    *x = (*x + mulmod(l - f, *y, l)) % l;
                }
            }
        }
        let Some(piv) = v.iter().position(|&x| x != 0) else { return false };
        let inv = powmod(v[piv], l - 2, l);
        for x in v.iter_mut() {
            *x = mulmod(*x, inv, l);
        }
        self.rows.push((piv, v));
        true
    }

    fn rank(&self) -> usize {
        self.rows.len()
    }
}

/// Step 2 for one prime l: the characters on zeta (if l | w) and the units
/// (compact: prod e_i^E_i, with exponents reduced modulo p - 1) reach rank
/// r + [l | w].
fn unit_saturated(ch: &Chars, units: &[Vec<BigInt>], w: u32, l: u64) -> Result<(), String> {
    let with_zeta = w as u64 % l == 0;
    let need = units.len() + with_zeta as usize;
    let support: Vec<usize> = (0..ch.elems.len()).filter(|&i| units.iter().any(|u| !u[i].is_zero())).collect();
    let mut ech = Echelon::new(l);
    for (tries, (p, a)) in ch.primes(l).enumerate() {
        if tries > 4 * need + 40 {
            return Err(format!("the certificate failed: no {} independent characters for l = {} (the unit index may be divisible by l)", need, l));
        }
        let dl = Dlog::new(p, l);
        let den_inv = powmod(ch.den.mod_floor(&BigInt::from(p)).to_u64().unwrap(), p - 2, p);
        let pm1 = BigInt::from(p - 1);
        let vals: HashMap<usize, u64> = support.iter().map(|&i| (i, reduce(&ch.elems[i], den_inv, a, p))).collect();
        let mut col = vec![];
        if with_zeta {
            col.push(dl.chi(reduce(&ch.zeta, den_inv, a, p))?);
        }
        for u in units {
            let mut y = 1u64;
            for &i in &support {
                if !u[i].is_zero() {
                    let e = u[i].mod_floor(&pm1).to_u64().unwrap();
                    let v = vals[&i];
                    if v == 0 {
                        return Err("an element of Gamma vanishes at a character prime".into());
                    }
                    y = mulmod(y, powmod(v, e, p), p);
                }
            }
            col.push(dl.chi(y)?);
        }
        ech.add(col);
        if ech.rank() == need {
            return Ok(());
        }
    }
    unreachable!("the primes 1 mod l are infinite")
}

/// The null space {x : A x = 0} over F_l of a matrix with `ncols` columns.
fn nullspace_mod(mut a: Vec<Vec<u64>>, ncols: usize, l: u64) -> Vec<Vec<u64>> {
    let mut pivots: Vec<usize> = vec![];
    let mut row = 0;
    for col in 0..ncols {
        let Some(pr) = (row..a.len()).find(|&i| a[i][col] != 0) else { continue };
        a.swap(row, pr);
        let inv = powmod(a[row][col], l - 2, l);
        for x in a[row].iter_mut() {
            *x = mulmod(*x, inv, l);
        }
        let pivot_row = a[row].clone();
        for (i, r) in a.iter_mut().enumerate() {
            if i != row && r[col] != 0 {
                let f = r[col];
                for (x, y) in r.iter_mut().zip(&pivot_row) {
                    *x = (*x + mulmod(l - f, *y, l)) % l;
                }
            }
        }
        pivots.push(col);
        row += 1;
        if row == a.len() {
            break;
        }
    }
    let is_pivot: HashSet<usize> = pivots.iter().cloned().collect();
    (0..ncols).filter(|c| !is_pivot.contains(c)).map(|free| {
        let mut x = vec![0u64; ncols];
        x[free] = 1;
        for (i, &pc) in pivots.iter().enumerate() {
            x[pc] = (l - a[i][free] % l) % l;
        }
        x
    }).collect()
}

/// Step 3 for one prime l | h*: rank_l [M~ | X] - rank_l M~ >= c + r +
/// [l | w] - rank_l M~ (M~: the relation matrix with a zero row for zeta),
/// i.e. the characters restricted to the left kernel K of M~ mod l reach
/// rank c + r + [l | w] - rank_l M~ there.
fn class_saturated(ch: &Chars, dense: &[Vec<i64>], c: usize, r: usize, w: u32, l: u64) -> Result<(), String> {
    let k = dense.len();
    let bl = l as i64;
    // the transpose of M~ (c x (k + 1)); its null space is K
    let mt: Vec<Vec<u64>> = (0..c).map(|j| (0..=k).map(|i| if i < k { dense[i][j].rem_euclid(bl) as u64 } else { 0 }).collect()).collect();
    let kern = nullspace_mod(mt, k + 1, l);
    let rank_m = k + 1 - kern.len();
    let need = c + r + (w as u64 % l == 0) as usize - rank_m;
    if need > kern.len() {
        return Err(format!("the certificate failed at l = {}: too few relations", l));
    }
    let mut ech = Echelon::new(l);
    if need == 0 {
        return Ok(());
    }
    for (tries, (p, a)) in ch.primes(l).enumerate() {
        if tries > 4 * need + 40 {
            return Err(format!("the certificate failed at l = {}: no {} independent characters (h* may be a proper multiple of h)", l, need));
        }
        let dl = Dlog::new(p, l);
        let den_inv = powmod(ch.den.mod_floor(&BigInt::from(p)).to_u64().unwrap(), p - 2, p);
        let mut chis = Vec::with_capacity(k + 1);
        for x in &ch.elems {
            chis.push(dl.chi(reduce(x, den_inv, a, p))?);
        }
        chis.push(dl.chi(reduce(&ch.zeta, den_inv, a, p))?);
        let col: Vec<u64> = kern.iter().map(|z| z.iter().zip(&chis).fold(0u64, |acc, (&zi, &xi)| (acc + mulmod(zi, xi, l)) % l)).collect();
        ech.add(col);
        if ech.rank() >= need {
            return Ok(());
        }
    }
    unreachable!("the primes 1 mod l are infinite")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn poly(c: &[i64]) -> Vec<BigInt> {
        c.iter().map(|&x| BigInt::from(x)).collect()
    }

    #[test]
    fn small_fields() {
        // (f, h, cyc, regulator) from PARI's bnfinit + bnfcertify (oracle)
        let cases: &[(&[i64], u64, &[u64], f64)] = &[
            (&[23, 0, 1], 3, &[3], 1.0),
            (&[-10, 0, 1], 2, &[2], 1.8184464592320668),
            (&[-2, 0, 0, 1], 1, &[], 1.3473773483293841),
            (&[-11, 0, 0, 1], 2, &[2], 5.5872066260609078),
            (&[1, 0, 0, 0, 1], 1, &[], 1.7627471740390861),
            (&[-1, -1, 0, 1], 1, &[], 0.28119957432296185),
        ];
        for (f, h, cyc, reg) in cases {
            let t = std::time::Instant::now();
            let pf = certify(&poly(f), &Limits::default()).unwrap_or_else(|e| panic!("{:?}: {}", f, e));
            eprintln!("{:?}: h {} cyc {:?} R in [{}, {}] M {} ({}) shown {} B {} l's {} class l's {:?} in {:.0} ms",
                f, pf.h, pf.cyc, pf.reg_lo, pf.reg_hi, pf.norm_bound, pf.norm_bound_kind.name(), pf.primes_shown, pf.index_bound, pf.unit_primes, pf.class_primes, t.elapsed().as_secs_f64() * 1e3);
            assert_eq!(pf.h, BigInt::from(*h));
            assert_eq!(pf.cyc, cyc.iter().map(|&x| BigInt::from(x)).collect::<Vec<_>>());
            assert!(pf.reg_lo <= reg * (1.0 + 1e-12) && pf.reg_hi >= reg * (1.0 - 1e-12), "{:?}: {} not in [{}, {}]", f, reg, pf.reg_lo, pf.reg_hi);
        }
    }

    /// The inputs of the saturation steps for Q[x]/(f), as certify builds
    /// them.
    fn setup(f: &[i64]) -> (Relations, Vec<Vec<i64>>, Vec<usize>, Embeddings, u32, f64) {
        let (b, _, rel) = bnfinit_with(&poly(f), &[]).unwrap();
        let emb = Embeddings::new(&rel.order).unwrap();
        let c = rel.fb.len();
        let dense: Vec<Vec<i64>> = rel.rels.iter().map(|rl| {
            let mut row = vec![0i64; c];
            for &(i, e) in rl {
                row[i] = e;
            }
            row
        }).collect();
        let sel = crate::linalg::independent_rows(&dense, c).unwrap();
        (rel, dense, sel, emb, b.w, b.regulator)
    }

    /// Soundness: units that span an index-l sublattice are refused at l
    /// (here a fundamental unit squared or cubed), and accepted as found.
    #[test]
    fn refuses_unsaturated_units() {
        for f in [&[-2i64, 0, 0, 1][..], &[-10, 0, 1], &[1, 0, 0, 0, 1]] {
            let (rel, dense, sel, emb, w, reg) = setup(f);
            let o = &rel.order;
            let r = emb.r1 + emb.r2 - 1;
            // (the GRH regulator as the target, as certify does: the first
            // units found can span a sublattice of index 2, rightly refused)
            let units = units_near(o, &emb, &rel.elems, &dense, &sel, r, reg).unwrap();
            let zeta = root_of_unity_generator(o, &emb, w).unwrap();
            let ch = Chars::new(o, &rel.elems, &zeta, rel.bound);
            for l in [2u64, 3, 5, 7] {
                assert!(unit_saturated(&ch, &units.exps, w, l).is_ok(), "{:?} l = {}", f, l);
            }
            for l in [2u64, 3] {
                let mut pw = units.exps.clone();
                for e in pw[0].iter_mut() {
                    *e *= BigInt::from(l);
                }
                assert!(unit_saturated(&ch, &pw, w, l).is_err(), "{:?}: u^{} accepted", f, l);
                // (and at another prime it is still saturated)
                assert!(unit_saturated(&ch, &pw, w, if l == 2 { 3 } else { 2 }).is_ok());
            }
        }
    }

    /// Soundness: relations spanning an index-l sublattice of the true
    /// relation lattice L are refused at l.  The sublattice: the kernel of
    /// v -> v_j mod l on L (index l when some relation has v_j prime to l),
    /// generated by v + (l - t_v) v0 (t_v = v_j / v0_j mod l; elements
    /// e_v e_v0^(l - t_v), integral) and l v0 (element e_v0^l), v0 a
    /// relation with v0_j prime to l.  The units of Gamma are unchanged.
    #[test]
    fn refuses_missing_relations() {
        let mut checked = 0;
        for (f, l) in [(&[5i64, 0, 1][..], 2u64), (&[23, 0, 1], 3), (&[-11, 0, 0, 1], 2), (&[-10, 0, 1], 2), (&[-2, 0, 0, 1], 3), (&[1, 0, 0, 0, 1], 5)] {
            let (rel, dense, sel, emb, w, _) = setup(f);
            let o = &rel.order;
            let c = rel.fb.len();
            let r = emb.r1 + emb.r2 - 1;
            let (h, _) = class_group_of(&dense, &sel, c).unwrap();
            let zeta = root_of_unity_generator(o, &emb, w).unwrap();
            let ch = Chars::new(o, &rel.elems, &zeta, rel.bound);
            if h.is_multiple_of(&BigInt::from(l)) {
                assert!(class_saturated(&ch, &dense, c, r, w, l).is_ok(), "{:?}", f);
            }
            let li = l as i64;
            let pw = |x: &Vec<BigInt>, e: i64| (0..e).fold(o.one(), |acc, _| o.mul(&acc, x));
            for col in 0..c.min(4) {
                let Some(i0) = (0..dense.len()).find(|&i| dense[i][col].rem_euclid(li) != 0) else { continue };
                let inv0 = powmod(dense[i0][col].rem_euclid(li) as u64, l - 2, l) as i64;
                let (mut d2, mut el) = (vec![], vec![]);
                for (i, row) in dense.iter().enumerate() {
                    if i == i0 {
                        continue;
                    }
                    let t = (row[col].rem_euclid(li) * inv0) % li;
                    let s = (li - t) % li;
                    d2.push(row.iter().zip(&dense[i0]).map(|(a, b)| a + s * b).collect::<Vec<i64>>());
                    el.push(o.mul(&rel.elems[i], &pw(&rel.elems[i0], s)));
                }
                d2.push(dense[i0].iter().map(|x| x * li).collect());
                el.push(pw(&rel.elems[i0], li));
                let sel2 = crate::linalg::independent_rows(&d2, c).unwrap();
                let (h2, _) = class_group_of(&d2, &sel2, c).unwrap();
                assert_eq!(h2, &h * BigInt::from(l), "{:?} column {}", f, col);
                let ch2 = Chars::new(o, &el, &zeta, rel.bound);
                assert!(class_saturated(&ch2, &d2, c, r, w, l).is_err(), "{:?}: the index-{} sublattice (column {}) accepted", f, l, col);
                checked += 1;
            }
        }
        assert!(checked >= 12, "{} cases", checked);
    }

    /// Soundness of step 1: with no factor base (bound 2), a non-principal
    /// prime ideal cannot be shown (Q(sqrt -5): the prime above 2, and
    /// Q(sqrt -23): those above 2, of order 3); with h = 1 every prime can
    /// (Q(i), Q(sqrt -163) up to its Minkowski bound 8).
    #[test]
    fn generation_needs_the_factor_base() {
        for (f, ok) in [(&[5i64, 0, 1][..], false), (&[6, -1, 1], false), (&[1, 0, 1], true), (&[41, -1, 1], true)] {
            let (o, _) = super::super::order::maximal_order(&poly(f)).unwrap();
            let emb = Embeddings::new(&o).unwrap();
            let dk = o.disc();
            let (m, _) = class_norm_bound(emb.r1, emb.r2, &dk).unwrap();
            let res = prove_generation(&o, &emb, &dk, 2, m.to_u64().unwrap(), &[]);
            assert_eq!(res.is_ok(), ok, "{:?}: {:?}", f, res);
        }
    }
}
